    ko: "투표를 만들거나 동네 작업을 올리고, 물품을 무료로 나누거나 Secrex로 일회성 암호화 비밀 메시지를 보낼 수 있습니다. 코드를 공유해 근처 사람들과 연결하세요. 계정이 필요 없습니다.",
