  "Use multiple choices to find when people can meet or which options they would accept. Each browser submits one ballot, and each option shows the share of ballots that picked it.": {
    ja: "複数選択で、集まれる時間や受け入れられる選択肢を調べられます。各ブラウザーから投票できるのは1回で、各選択肢にはそれを選んだ投票の割合が表示されます。",
    ko: "복수 선택으로 가능한 시간이나 수용할 수 있는 옵션을 찾을 수 있습니다. 브라우저당 한 번 투표하며 각 항목을 선택한 투표지 비율이 표시됩니다.",
    fr: "Utilisez les choix multiples pour trouver un créneau commun ou les options acceptables. Chaque navigateur soumet un bulletin, et chaque option affiche la part des bulletins qui l’ont retenue.",
    pt: "Use a seleção múltipla para descobrir os horários ou as opções que funcionam para o grupo. Cada navegador envia uma cédula e cada opção mostra a proporção de cédulas que a selecionaram.",
    es: "Usa la selección múltiple para encontrar horarios u opciones que sirvan al grupo. Cada navegador envía una papeleta y cada opción muestra la proporción de papeletas que la eligieron.",
    de: "Nutze die Mehrfachauswahl, um passende Termine oder akzeptable Optionen zu finden. Pro Browser wird ein Stimmzettel abgegeben. Jede Option zeigt den Anteil der Stimmzettel, die sie gewählt haben.",
    it: "Usa la scelta multipla per trovare orari o opzioni accettabili per il gruppo. Ogni browser invia una scheda e ogni opzione mostra la quota di schede che l’hanno scelta.",
  },
  "Pickup requests save a proposed time and a hash of a random cookie for that giveaway. They do not ask for contact details.": {
    ja: "受け取り申請では、希望時刻と、その譲渡専用のランダムな Cookie のハッシュを保存します。連絡先は求めません。",
    ko: "수령 신청은 제안 시간과 해당 나눔의 임의 쿠키 해시를 저장합니다. 연락처는 요청하지 않습니다.",
    fr: "Les demandes de retrait enregistrent une heure proposée et le hachage d’un cookie aléatoire propre au don. Elles ne demandent pas de coordonnées.",
    pt: "Pedidos de retirada salvam o horário proposto e o hash de um cookie aleatório para aquela doação. Não solicitam dados de contato.",
    es: "Las solicitudes de recogida guardan la hora propuesta y un hash de una cookie aleatoria para esa donación. No solicitan datos de contacto.",
    de: "Abholanfragen speichern die vorgeschlagene Zeit und den Hash eines zufälligen Cookies für dieses Angebot. Kontaktdaten sind nicht erforderlich.",
    it: "Le richieste di ritiro salvano l’ora proposta e l’hash di un cookie casuale per quel regalo. Non richiedono recapiti.",
  },
