    de: "Bitte Nachbarn um einen kostenlosen Gegenstand. Spendende können öffentlich antworten und Telefonnummer oder E-Mail separat verschlüsseln. Du kannst jemanden auswählen oder den Gegenstand als erhalten markieren, damit keine weiteren Angebote eingehen.",
    it: "Chiedi ai vicini un oggetto gratuito. I donatori possono rispondere pubblicamente e lasciare un telefono o un’e-mail cifrati separatamente. Puoi scegliere un donatore o segnare l’oggetto come ricevuto per fermare le offerte.",
