    pt: "Apenas áreas aproximadas. Carregar esta visualização conecta-se ao OpenFreeMap, que recebe seu endereço IP e as áreas do mapa que você visualiza. O conteúdo das publicações permanece no ScaleTag.",
    es: "Solo zonas aproximadas. Al cargar esta vista se conecta con OpenFreeMap, que recibe tu dirección IP y las zonas del mapa que ves. El contenido de las publicaciones permanece en ScaleTag.",
