  "You’re offline. Publishing, voting, likes and replies need a connection. Results shown may be out of date.": {
    ja: "現在オフラインです。投稿、投票、いいね、返信には接続が必要です。表示されている結果は最新ではない可能性があります。",
    ko: "오프라인 상태입니다. 게시, 투표, 좋아요, 댓글 작성에는 연결이 필요합니다. 표시된 결과가 최신이 아닐 수 있습니다.",
    fr: "Vous êtes hors ligne. Publier, voter, aimer ou répondre nécessite une connexion. Les résultats affichés peuvent dater.",
    pt: "Você está offline. Publicação, votação, curtidas e respostas precisam de conexão. Os resultados exibidos podem estar desatualizados.",
    es: "Estás sin conexión. Publicar, votar, dar Me gusta y enviar respuestas requieren conexión. Los resultados mostrados pueden estar desactualizados.",
    de: "Du bist offline. Veröffentlichen, Abstimmen, „Gefällt mir“-Angaben und Antworten erfordern eine Verbindung. Angezeigte Ergebnisse sind möglicherweise veraltet.",
    it: "Sei offline. Pubblicazione, voti, Mi piace e risposte richiedono una connessione. I risultati mostrati potrebbero non essere aggiornati.",
  },
  "Keep a little curiosity on your home screen. Publishing, voting and live results still need an internet connection.": {
    ja: "ScaleTag をホーム画面に。投稿、投票、リアルタイム結果の確認にはインターネット接続が必要です。",
    ko: "홈 화면에 ScaleTag를 두고 이용하세요. 게시, 투표, 실시간 결과 확인에는 인터넷 연결이 필요합니다.",
    fr: "Gardez ScaleTag sur votre écran d’accueil. La publication, le vote et les résultats en direct nécessitent toujours une connexion Internet.",
    pt: "Mantenha um pouco de curiosidade na sua tela inicial. Publicar, votar e ver resultados ao vivo ainda precisam de conexão com a internet.",
    es: "Ten un poco de curiosidad en tu pantalla de inicio. Publicar, votar y ver resultados en vivo siguen requiriendo conexión a internet.",
    de: "Hol dir ein wenig Neugier auf deinen Startbildschirm. Veröffentlichen, Abstimmen und Live-Ergebnisse erfordern weiterhin eine Internetverbindung.",
    it: "Tieni un po’ di curiosità sulla tua schermata Home. Pubblicazione, voti e risultati in tempo reale richiedono comunque una connessione a internet.",
  },
