    fr: "L’autorisation de localisation est requise. Activez-la dans les réglages de votre navigateur puis réessayez.",
    pt: "A permissão de localização é necessária. Permita o acesso nas configurações do navegador e tente novamente.",
    es: "Se requiere permiso de ubicación. Actívalo en la configuración de tu navegador e inténtalo de nuevo.",
