  "Public for 30 days. Backed up for recovery.": {
    ja: "30日間公開され、復旧用バックアップを保持します。",
    ko: "30일간 공개되며 복구를 위해 백업됩니다.",
    fr: "Public pendant 30 jours. Sauvegardé pour la reprise.",
    pt: "Público por 30 dias. Com backup para recuperação.",
    es: "Público durante 30 días. Con copia de seguridad para recuperación.",
    de: "30 Tage öffentlich. Zur Wiederherstellung gesichert.",
    it: "Pubblico per 30 giorni. Salvato nei backup per il ripristino.",
  },
  "Posts leave the website 30 days after publication. Private daily backups are retained for up to 90 days after each backup is created. Save anything you need before the public link expires.": {
    ja: "投稿は公開から30日後にウェブサイトから削除されます。非公開の日次バックアップは各作成日から最大90日間保持されます。公開リンクが切れる前に必要な情報を保存してください。",
    ko: "게시물은 게시 30일 후 웹사이트에서 삭제됩니다. 비공개 일일 백업은 생성일로부터 최대 90일간 보관됩니다. 공개 링크가 만료되기 전에 필요한 내용을 저장하세요.",
    fr: "Les publications quittent le site 30 jours après leur mise en ligne. Les sauvegardes quotidiennes privées sont conservées jusqu’à 90 jours. Enregistrez ce dont vous avez besoin avant expiration.",
    pt: "As publicações saem do site 30 dias após serem publicadas. Backups diários privados são mantidos por até 90 dias após a criação de cada backup. Salve tudo o que precisar antes que o link público expire.",
    es: "Las publicaciones se retiran del sitio web 30 días después de su publicación. Las copias de seguridad diarias privadas se conservan hasta 90 días después de la creación de cada copia. Guarda lo que necesites antes de que expire el enlace público.",
    de: "Beiträge werden 30 Tage nach der Veröffentlichung von der Website entfernt. Private tägliche Backups werden bis zu 90 Tage nach Erstellung des jeweiligen Backups aufbewahrt. Speichere alles, was du brauchst, bevor der öffentliche Link abläuft.",
    it: "I post vengono rimossi dal sito 30 giorni dopo la pubblicazione. I backup giornalieri privati vengono conservati fino a 90 giorni dalla creazione di ciascun backup. Salva tutto ciò che ti serve prima della scadenza del link pubblico.",
  },
  "Up to 2 JPEG, PNG or WebP photos. Each original must be at most 1 MiB (1,048,576 bytes). Originals are uploaded to the server for validation. Photos over 600 KiB are compressed to at most 300 KiB; smaller photos keep as much quality as possible. Photos are public; check for faces, addresses and other private details.": {
    ja: "JPEG、PNG、WebP 形式の写真を最大2枚まで（各元画像は 1 MiB / 1,048,576 バイト以下）。元画像は検証のためサーバーに送信され、600 KiB 超の画像は 300 KiB 以下に圧縮されます。写真は公開されるため、顔や住所などの写り込みをご確認ください。",
    ko: "JPEG, PNG 또는 WebP 사진 최대 2장까지 첨부할 수 있으며 원본은 장당 최대 1 MiB(1,048,576바이트)입니다. 원본은 서버 검증을 위해 업로드되며 600 KiB를 초과하는 사진은 300 KiB 이하로 압축됩니다. 사진은 공개되므로 얼굴이나 주소 등 개인정보가 포함되지 않았는지 확인하세요.",
    fr: "Jusqu’à 2 photos JPEG, PNG ou WebP (1 Mio / 1 048 576 octets max par original). Les originaux sont vérifiés par le serveur ; ceux de plus de 600 Kio sont compressés à 300 Kio max. Les photos sont publiques : vérifiez qu’aucun visage ni adresse n’apparaît.",
    pt: "Até 2 fotos JPEG, PNG ou WebP. Cada original deve ter no máximo 1 MiB (1.048.576 bytes). Os originais são enviados ao servidor para validação. Fotos acima de 600 KiB são comprimidas para no máximo 300 KiB; fotos menores mantêm a maior qualidade possível. As fotos são públicas; verifique se há rostos, endereços e outros detalhes privados.",
    es: "Hasta 2 fotos JPEG, PNG o WebP. Cada original debe tener un tamaño máximo de 1 MiB (1 048 576 bytes). Los originales se suben al servidor para su validación. Las fotos de más de 600 KiB se comprimen a un máximo de 300 KiB; las fotos más pequeñas conservan la mayor calidad posible. Las fotos son públicas; revisa si hay rostros, direcciones u otros datos privados.",
    de: "Bis zu 2 JPEG-, PNG- oder WebP-Fotos. Jedes Original darf höchstens 1 MiB (1.048.576 Bytes) groß sein. Originale werden zur Prüfung auf den Server hochgeladen. Fotos über 600 KiB werden auf höchstens 300 KiB komprimiert; kleinere Fotos behalten so viel Qualität wie möglich. Fotos sind öffentlich; achte auf Gesichter, Adressen und andere private Details.",
    it: "Fino a 2 foto JPEG, PNG o WebP. Ogni foto originale non deve superare 1 MiB (1.048.576 byte). Gli originali vengono caricati sul server per la convalida. Le foto superiori a 600 KiB vengono compresse fino a un massimo di 300 KiB; le foto più piccole mantengono la massima qualità possibile. Le foto sono pubbliche; controlla che non ci siano volti, indirizzi o altri dettagli privati.",
  },
