    ko: "잠금을 해제하면 이 비밀 메시지는 짧은 열람 시간 동안 현재 탭에만 연결되며 다른 사람은 열 수 없습니다. 확인 후 ‘종료 및 파기’를 누르세요.",
    fr: "Le déverrouillage associe ce secret à votre onglet actuel pour un court instant et bloque tout autre accès. Cliquez sur Terminer et détruire une fois fini.",
