  "I understand that my name and message are public until this task leaves the website, 30 days after it was published. My phone/email is not public: it is encrypted and can be decrypted with the task management password; encrypted backups are kept for up to 90 days. I have not put contact details in my name or message.": {
    ja: "お名前とメッセージは公開から30日後にタスクがサイトから削除されるまで公開されることを理解しています。電話番号とメールアドレスは公開されず、暗号化されて管理パスワードでのみ復号可能で、暗号化バックアップは最大90日間保持されます。名前やメッセージ欄に連絡先を含めていません。",
    ko: "게시 30일 후 작업이 웹사이트에서 삭제될 때까지 이름과 메시지가 공개됨을 이해합니다. 전화번호와 이메일은 공개되지 않고 암호화되어 작업 관리 비밀번호로만 복호화되며 암호화 백업은 최대 90일간 보관됩니다. 이름과 메시지에 연락처를 적지 않았습니다.",
    fr: "Je comprends que mon nom et mon message restent publics pendant 30 jours après publication. Mon téléphone/e-mail reste privé, chiffré et déchiffrable uniquement avec le mot de passe de gestion (sauvegardes chiffrées jusqu’à 90 jours). Je n’ai mis aucune coordonnée dans mon nom ni mon message.",
    pt: "Entendo que meu nome e minha mensagem são públicos até que esta tarefa saia do site, 30 dias após a publicação. Meu telefone/e-mail não é público: ele é criptografado e pode ser descriptografado com a senha de gerenciamento da tarefa; backups criptografados são mantidos por até 90 dias. Não coloquei dados de contato no meu nome nem na minha mensagem.",
    es: "Entiendo que mi nombre y mi mensaje son públicos hasta que esta tarea se retire del sitio web, 30 días después de haberse publicado. Mi teléfono/correo electrónico no es público: está cifrado y puede descifrarse con la contraseña de gestión de la tarea; las copias de seguridad cifradas se conservan durante un máximo de 90 días. No he incluido datos de contacto en mi nombre ni en mi mensaje.",
    de: "Mir ist bewusst, dass mein Name und meine Nachricht öffentlich sind, bis diese Aufgabe 30 Tage nach ihrer Veröffentlichung von der Website entfernt wird. Meine Telefonnummer/E-Mail-Adresse ist nicht öffentlich: Sie ist verschlüsselt und kann mit dem Passwort zur Aufgabenverwaltung entschlüsselt werden; verschlüsselte Backups werden bis zu 90 Tage lang aufbewahrt. Ich habe keine Kontaktdaten in meinem Namen oder meiner Nachricht angegeben.",
    it: "Comprendo che il mio nome e il mio messaggio sono pubblici finché questa attività non viene rimossa dal sito web, 30 giorni dopo la pubblicazione. Il mio telefono/la mia email non sono pubblici: vengono cifrati e possono essere decifrati con la password di gestione dell'attività; i backup cifrati vengono conservati fino a 90 giorni. Non ho inserito dati di contatto nel mio nome o nel mio messaggio.",
  },
