    de: "Ich stimme zu, dass der ungefähre Bereich meiner Aufgabe öffentlich auf der Karte angezeigt wird. Dies garantiert keine Anonymität.",
    it: "Accetto di mostrare pubblicamente sulla mappa l’area approssimativa della mia attività. Questo non garantisce l’anonimato.",
