    fr: "Conservez précieusement votre mot de passe de gestion. S’il est perdu, les coordonnées chiffrées ne pourront pas être récupérées.",
    pt: "Guarde sua senha de gerenciamento em segurança. Se ela for perdida, os dados de contato criptografados não poderão ser recuperados.",
    es: "Guarda tu contraseña de gestión en un lugar seguro. Si se pierde, no se podrán recuperar los datos de contacto cifrados.",
