    ja: "管理ページでのみ閲覧可能です。返信者がこのタスクの連絡用に共有した情報ですので再公開しないでください。これらの情報はタスクとともに次の日時に削除されます：",
    ko: "관리 페이지에서만 보입니다. 응답자가 이 작업과 관련해 연락할 수 있도록 남긴 정보이므로 다시 공개하지 마세요. 이 정보는 작업과 함께 다음 날짜에 삭제됩니다: ",
